def d_func(n):
    if n <= 1:
        return -1 # Undefined/Invalid
    count = 0
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    if n > 1 and count == 0: # If n is prime
        return 0
    return count

print(f"d(10): {d_func(10)}")
print(f"d(745): {d_func(745)}")
